{
  "PROP-56ad1eb2-inv-018": {
    "property_id": "PROP-56ad1eb2-inv-018",
    "audit_result": {
      "property_id": "PROP-56ad1eb2-inv-018",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::verify_data_column_sidecar_for_gossip::L688",
      "proof_trace": "Post-Fulu spec requires get_beacon_proposer_index to return proposer_lookahead[slot % SLOTS_PER_EPOCH]. All three gossip verification paths (data_column L688, blob L536, block L991) call get_beacon_proposer_indices instead, which always recomputes from active validators without reading proposer_lookahead, violating the cached-lookup requirement.",
      "attack_scenario": "If proposer_lookahead and recomputed values diverge due to state inconsistencies in cheap_state_advance partial updates, different nodes may accept/reject the same block based on which code path executes, causing consensus splits.",
      "checklist_id": "PROP-56ad1eb2-inv-018"
    },
    "text": "get_beacon_proposer_index must return proposer_lookahead[slot % SLOTS_PER_EPOCH], not recompute.",
    "assertion": "forall slot s: get_beacon_proposer_index(state,s)==state.proposer_lookahead[s%SLOTS_PER_EPOCH]",
    "covers": "SG-005",
    "severity": "HIGH",
    "type": "invariant"
  }
}

